        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 13574.0, "series": [{"data": [[0.0, 13406.0], [100.0, 18.0], [200.0, 1.0]], "isOverall": false, "label": "SeleccionTarifaYCantidad", "isController": false}, {"data": [[0.0, 13242.0], [100.0, 15.0], [200.0, 2.0]], "isOverall": false, "label": "Pago", "isController": false}, {"data": [[0.0, 13574.0], [100.0, 18.0], [200.0, 1.0]], "isOverall": false, "label": "Tarifas", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 200.0, "title": "Response Time Distribution"}},
